-- TPS1-Admin full Supabase reset
-- Chạy 1 lần để tạo lại toàn bộ schema, quyền và seed catalog.
-- Cảnh báo: script này xóa bảng cũ rồi tạo lại từ đầu.

create extension if not exists pgcrypto;

-- Drop in dependency order
 drop table if exists public.quote_history cascade;
 drop table if exists public.quotes cascade;
 drop table if exists public.products cascade;

create table public.products (
  id uuid primary key default gen_random_uuid(),
  local_product_id text not null unique,
  sku text,
  name text not null,
  category text not null,
  sub_category text,
  unit text not null default 'Kg',
  pack_size text,
  price_wholesale numeric(14,2) not null default 0,
  price_retail numeric(14,2) not null default 0,
  supplier text,
  origin text,
  active boolean not null default true,
  tags text[] not null default '{}'::text[],
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.quotes (
  id uuid primary key default gen_random_uuid(),
  local_quote_id text not null unique,
  lead_id text not null,
  quote_code text,
  lead_name text not null,
  lead_phone text not null,
  lead_email text,
  lead_category text,
  lead_source text,
  lead_snapshot jsonb not null default '{}'::jsonb,
  quote_snapshot jsonb not null default '{}'::jsonb,
  price_type text not null default 'wholesale',
  status text not null default 'draft',
  result text,
  items jsonb not null default '[]'::jsonb,
  subtotal numeric(14,2) not null default 0,
  discount_percent numeric(5,2) not null default 0,
  discount_amount numeric(14,2) not null default 0,
  shipping_amount numeric(14,2) not null default 0,
  vat_rate numeric(5,2) not null default 0,
  total_before_vat numeric(14,2) not null default 0,
  vat_amount numeric(14,2) not null default 0,
  deposit_amount numeric(14,2) not null default 0,
  grand_total numeric(14,2) not null default 0,
  balance_amount numeric(14,2) not null default 0,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  closed_at timestamptz
);

create table public.quote_history (
  id uuid primary key default gen_random_uuid(),
  local_quote_id text not null,
  lead_id text not null,
  action text not null,
  from_status text,
  to_status text,
  note text,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint quote_history_local_quote_fk
    foreign key (local_quote_id)
    references public.quotes (local_quote_id)
    on delete cascade
);

create index quotes_lead_id_idx on public.quotes (lead_id);
create index quotes_status_idx on public.quotes (status);
create index quote_history_quote_idx on public.quote_history (local_quote_id);
create index quote_history_lead_idx on public.quote_history (lead_id);
create index products_category_idx on public.products (category);
create index products_name_idx on public.products (name);

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_products_set_updated_at on public.products;
create trigger trg_products_set_updated_at
before update on public.products
for each row
execute function public.set_updated_at();

drop trigger if exists trg_quotes_set_updated_at on public.quotes;
create trigger trg_quotes_set_updated_at
before update on public.quotes
for each row
execute function public.set_updated_at();

alter table public.products enable row level security;
alter table public.quotes enable row level security;
alter table public.quote_history enable row level security;

grant usage on schema public to anon, authenticated;
grant select, insert, update, delete on table public.products to anon, authenticated;
grant select, insert, update, delete on table public.quotes to anon, authenticated;
grant select, insert, update, delete on table public.quote_history to anon, authenticated;

drop policy if exists "products_select_all" on public.products;
create policy "products_select_all"
on public.products
for select
using (true);

drop policy if exists "products_insert_all" on public.products;
create policy "products_insert_all"
on public.products
for insert
with check (true);

drop policy if exists "products_update_all" on public.products;
create policy "products_update_all"
on public.products
for update
using (true)
with check (true);

drop policy if exists "products_delete_all" on public.products;
create policy "products_delete_all"
on public.products
for delete
using (true);

drop policy if exists "quotes_select_all" on public.quotes;
create policy "quotes_select_all"
on public.quotes
for select
using (true);

drop policy if exists "quotes_insert_all" on public.quotes;
create policy "quotes_insert_all"
on public.quotes
for insert
with check (true);

drop policy if exists "quotes_update_all" on public.quotes;
create policy "quotes_update_all"
on public.quotes
for update
using (true)
with check (true);

drop policy if exists "quotes_delete_all" on public.quotes;
create policy "quotes_delete_all"
on public.quotes
for delete
using (true);

drop policy if exists "quote_history_select_all" on public.quote_history;
create policy "quote_history_select_all"
on public.quote_history
for select
using (true);

drop policy if exists "quote_history_insert_all" on public.quote_history;
create policy "quote_history_insert_all"
on public.quote_history
for insert
with check (true);

drop policy if exists "quote_history_update_all" on public.quote_history;
create policy "quote_history_update_all"
on public.quote_history
for update
using (true)
with check (true);

drop policy if exists "quote_history_delete_all" on public.quote_history;
create policy "quote_history_delete_all"
on public.quote_history
for delete
using (true);

